-- ============================================================================
-- SC5 GO-LIVE (HELD): Contract & Supplier Management (contracts) flips from coming_soon to available.
--
-- DEPLOY GATE: do NOT run this until a NextGen production upload serves
-- /dashboard/apps/contracts (see `apps/contracts` in the served DashboardPage chunk).
-- A PRACTICE COURSE: no Suite app and no Suite upload are involved.
--
-- Generated by tools/course-waves/contracts/gen_golive.py from wave.json, the
-- three manifests and the 21 committed bank JSONs. Before the flip it asserts,
-- inside this transaction: the platform (the three columns and their two
-- checks, academy_claim_practice_certificate with its grants, course_type in
-- academy_verify_certificate); the practice row (module supply_chain, path_order
-- 79 unique, no prerequisite, review 2027-09-27, sources checked
-- 2026-09-27); no capstone row; each tier's structure exactly as its
-- manifest gives it; 90 module questions (15 a module) and 42 final questions
-- a tier, four options, answer indices 0 to 3 spread within the bank gate's
-- band, an explanation each, and a content digest equal to the committed
-- banks'; no dash or passage id in any question. A refusal raises and aborts.
-- No transaction lines of its own. Idempotent.
-- ============================================================================

do $$
declare
  v_app public.academy_apps;
  v_n   integer;
  v_bad text;
  v_d   text;
begin
  -- -------------------------------------------------------------- platform
  if (select count(*) from information_schema.columns
       where table_schema = 'public' and table_name = 'academy_apps'
         and column_name in ('course_type', 'review_date', 'sources_checked_on')) <> 3 then
    raise exception 'SC5 go-live refused: academy_apps lacks the course type columns (apply 20261116_sc5_contracts_platform_course_types.sql first)';
  end if;
  if (select count(*) from pg_constraint
       where conrelid = 'public.academy_apps'::regclass
         and conname in ('academy_apps_course_type_check', 'academy_apps_practice_dates_check')) <> 2 then
    raise exception 'SC5 go-live refused: a course type check constraint is missing';
  end if;
  if to_regprocedure('public.academy_claim_practice_certificate(text,text)') is null then
    raise exception 'SC5 go-live refused: academy_claim_practice_certificate(text, text) is missing';
  end if;
  if not has_function_privilege('authenticated', 'public.academy_claim_practice_certificate(text,text)', 'execute')
     or has_function_privilege('anon', 'public.academy_claim_practice_certificate(text,text)', 'execute') then
    raise exception 'SC5 go-live refused: the practice certificate claim is not granted to authenticated alone';
  end if;
  if position('course_type' in pg_get_functiondef('public.academy_verify_certificate(text)'::regprocedure)) = 0 then
    raise exception 'SC5 go-live refused: academy_verify_certificate does not return course_type';
  end if;

  -- ------------------------------------------------------------ the row
  select * into v_app from public.academy_apps where slug = 'contracts';
  if v_app.slug is null then
    raise exception 'SC5 go-live refused: the contracts row is not seeded (apply 20261116_sc5_contracts_course.sql first)';
  end if;
  if v_app.name is distinct from 'Contract & Supplier Management' or v_app.module is distinct from 'supply_chain'
     or v_app.path_order is distinct from 79 or v_app.prereq_slug is not null then
    raise exception 'SC5 go-live refused: the contracts row is not the catalogue row the course migration writes (name %, module %, path_order %, prereq %)',
      v_app.name, v_app.module, v_app.path_order, v_app.prereq_slug;
  end if;
  if v_app.course_type is distinct from 'practice'
     or v_app.review_date is distinct from date '2027-09-27'
     or v_app.sources_checked_on is distinct from date '2026-09-27' then
    raise exception 'SC5 go-live refused: contracts is not the practice row (type %, review %, checked %)',
      v_app.course_type, v_app.review_date, v_app.sources_checked_on;
  end if;
  select count(*) into v_n from public.academy_apps where path_order = 79;
  if v_n <> 1 then
    raise exception 'SC5 go-live refused: path_order 79 is held by % rows', v_n;
  end if;
  if exists (select 1 from public.academy_capstones where app_slug = 'contracts') then
    raise exception 'SC5 go-live refused: a practice course carries no capstone row';
  end if;

  -- ---------------------------------------------------------------- beginner
  if not exists (select 1 from public.academy_course_structures
                  where app_slug = 'contracts' and tier = 'beginner' and active
                    and structure = '{"modules":[{"key":"m01-contract-management-and-its-sources","title":"Contract Management and Its Sources","lesson_keys":["l01-what-contract-management-is","l02-the-contract-lifecycle","l03-owners-managers-and-the-supplier","l04-the-sources-and-their-dates","l05-a-practice-course-and-its-written-work"]},{"key":"m02-award-handover-and-mobilisation","title":"Award Handover and Mobilisation","lesson_keys":["l01-from-tender-team-to-contract-team","l02-the-contract-management-plan","l03-the-kick-off-meeting","l04-mobilisation-and-first-deliveries"]},{"key":"m03-reading-the-contract-you-manage","title":"Reading the Contract You Manage","lesson_keys":["l01-scope-and-specification","l02-the-price-basis","l03-order-of-precedence","l04-clauses-a-contract-manager-uses"]},{"key":"m04-kpis-and-service-levels","title":"KPIs and Service Levels","lesson_keys":["l01-what-a-kpi-measures","l02-designing-an-indicator","l03-service-levels-and-service-credits","l04-data-evidence-and-a-disputed-score"]},{"key":"m05-payment-records-and-the-audit-trail","title":"Payment, Records and the Audit Trail","lesson_keys":["l01-checking-an-invoice","l02-certifying-work-done","l03-records-that-survive-an-audit","l04-correspondence-and-instructions"]},{"key":"m06-nigerian-content-in-execution","title":"Nigerian Content in Execution","lesson_keys":["l01-the-content-act-and-the-board","l02-first-consideration-in-practice","l03-nigerians-employed-and-trained","l04-plans-and-reports-a-contract-carries","l05-preparing-for-the-associate-exam"]}]}'::jsonb) then
    raise exception 'SC5 go-live refused: the beginner structure row is missing, inactive or not the manifest''s structure';
  end if;
  select string_agg(k, ', ' order by k) into v_bad from (
    select k from unnest(array['m01-contract-management-and-its-sources', 'm02-award-handover-and-mobilisation', 'm03-reading-the-contract-you-manage', 'm04-kpis-and-service-levels', 'm05-payment-records-and-the-audit-trail', 'm06-nigerian-content-in-execution']) k
     where (select count(*) from public.academy_quiz_questions q
             where q.app_slug = 'contracts' and q.tier = 'beginner' and q.scope = 'module'
               and q.module_key = k and q.active) <> 15) x;
  if v_bad is not null then
    raise exception 'SC5 go-live refused: beginner module bank(s) without exactly 15 active questions: %', v_bad;
  end if;
  select count(*) into v_n from public.academy_quiz_questions
   where app_slug = 'contracts' and tier = 'beginner' and scope = 'final' and active;
  if v_n <> 42 then
    raise exception 'SC5 go-live refused: the beginner final exam holds % active questions, not 42', v_n;
  end if;
  select count(*) into v_n from public.academy_quiz_questions where app_slug = 'contracts' and tier = 'beginner';
  if v_n <> 132 then
    raise exception 'SC5 go-live refused: the beginner tier holds % questions, not 132', v_n;
  end if;
  select md5(string_agg(tier || '|' || scope || '|' || coalesce(module_key, '') || '|' || ord || '|' || md5(prompt)
                        || '|' || md5(options->>0) || '|' || md5(options->>1) || '|' || md5(options->>2) || '|' || md5(options->>3)
                        || '|' || answer_index || '|' || md5(coalesce(explanation, '')), ','
                        order by case scope when 'module' then 0 else 1 end, left(coalesce(module_key, ''), 3), ord))
    into v_d
    from public.academy_quiz_questions where app_slug = 'contracts' and tier = 'beginner';
  if v_d is distinct from '42533e116bd67d18c7a6d881470cdebb' then
    raise exception 'SC5 go-live refused: the beginner questions are not the committed banks (content digest % where the banks give 42533e116bd67d18c7a6d881470cdebb)', v_d;
  end if;
  -- ---------------------------------------------------------------- intermediate
  if not exists (select 1 from public.academy_course_structures
                  where app_slug = 'contracts' and tier = 'intermediate' and active
                    and structure = '{"modules":[{"key":"m01-segmenting-suppliers","title":"Segmenting Suppliers","lesson_keys":["l01-why-suppliers-get-different-attention","l02-profit-impact-and-supply-risk","l03-tiering-contracts-by-risk-and-value","l04-relationship-models-for-each-segment","l05-segmenting-the-ekene-suppliers"]},{"key":"m02-supplier-performance-reviews","title":"Supplier Performance Reviews","lesson_keys":["l01-the-review-cycle","l02-the-scorecard-and-its-evidence","l03-running-the-review-meeting","l04-improvement-plans-that-close"]},{"key":"m03-variations-and-change-control","title":"Variations and Change Control","lesson_keys":["l01-what-counts-as-a-change","l02-authority-to-instruct-a-change","l03-assessing-a-change-request","l04-limits-on-modifying-a-public-contract","l05-the-change-register"]},{"key":"m04-supplier-risk-and-resilience","title":"Supplier Risk and Resilience","lesson_keys":["l01-risks-a-supplier-carries-in","l02-financial-standing-and-early-warnings","l03-single-sources-and-continuity","l04-resolution-planning"]},{"key":"m05-nigerian-content-obligations-in-depth","title":"Nigerian Content Obligations in Depth","lesson_keys":["l01-the-nigerian-content-plan","l02-employment-and-expatriate-positions","l03-training-and-capacity-building","l04-performance-reports-and-monitoring"]},{"key":"m06-poor-performance-and-remedies","title":"Poor Performance and Remedies","lesson_keys":["l01-from-concern-to-formal-notice","l02-remedies-the-contract-gives","l03-recording-poor-performance","l04-preparing-for-the-professional-exam"]}]}'::jsonb) then
    raise exception 'SC5 go-live refused: the intermediate structure row is missing, inactive or not the manifest''s structure';
  end if;
  select string_agg(k, ', ' order by k) into v_bad from (
    select k from unnest(array['m01-segmenting-suppliers', 'm02-supplier-performance-reviews', 'm03-variations-and-change-control', 'm04-supplier-risk-and-resilience', 'm05-nigerian-content-obligations-in-depth', 'm06-poor-performance-and-remedies']) k
     where (select count(*) from public.academy_quiz_questions q
             where q.app_slug = 'contracts' and q.tier = 'intermediate' and q.scope = 'module'
               and q.module_key = k and q.active) <> 15) x;
  if v_bad is not null then
    raise exception 'SC5 go-live refused: intermediate module bank(s) without exactly 15 active questions: %', v_bad;
  end if;
  select count(*) into v_n from public.academy_quiz_questions
   where app_slug = 'contracts' and tier = 'intermediate' and scope = 'final' and active;
  if v_n <> 42 then
    raise exception 'SC5 go-live refused: the intermediate final exam holds % active questions, not 42', v_n;
  end if;
  select count(*) into v_n from public.academy_quiz_questions where app_slug = 'contracts' and tier = 'intermediate';
  if v_n <> 132 then
    raise exception 'SC5 go-live refused: the intermediate tier holds % questions, not 132', v_n;
  end if;
  select md5(string_agg(tier || '|' || scope || '|' || coalesce(module_key, '') || '|' || ord || '|' || md5(prompt)
                        || '|' || md5(options->>0) || '|' || md5(options->>1) || '|' || md5(options->>2) || '|' || md5(options->>3)
                        || '|' || answer_index || '|' || md5(coalesce(explanation, '')), ','
                        order by case scope when 'module' then 0 else 1 end, left(coalesce(module_key, ''), 3), ord))
    into v_d
    from public.academy_quiz_questions where app_slug = 'contracts' and tier = 'intermediate';
  if v_d is distinct from 'fba9d437cb15a5153f8048ae33866096' then
    raise exception 'SC5 go-live refused: the intermediate questions are not the committed banks (content digest % where the banks give fba9d437cb15a5153f8048ae33866096)', v_d;
  end if;
  -- ---------------------------------------------------------------- advanced
  if not exists (select 1 from public.academy_course_structures
                  where app_slug = 'contracts' and tier = 'advanced' and active
                    and structure = '{"modules":[{"key":"m01-contract-strategy","title":"Contract Strategy","lesson_keys":["l01-what-a-contract-strategy-decides","l02-delivery-models-and-make-or-buy","l03-packaging-the-work","l04-choosing-the-price-basis","l05-a-strategy-for-an-ekene-campaign"]},{"key":"m02-claims","title":"Claims","lesson_keys":["l01-what-a-claim-is","l02-notice-and-its-timing","l03-entitlement-and-evidence","l04-assessing-a-claim-fairly"]},{"key":"m03-disputes-and-their-resolution","title":"Disputes and Their Resolution","lesson_keys":["l01-the-escalation-ladder","l02-negotiation-and-mediation","l03-expert-determination-and-adjudication","l04-arbitration-and-the-courts"]},{"key":"m04-termination-step-in-and-exit","title":"Termination, Step-In and Exit","lesson_keys":["l01-grounds-for-termination","l02-step-in-and-other-interventions","l03-exit-planning","l04-a-supplier-in-distress"]},{"key":"m05-close-out-and-lessons-learned","title":"Close-Out and Lessons Learned","lesson_keys":["l01-completion-and-acceptance","l02-the-final-account","l03-evaluating-the-supplier-at-close","l04-lessons-learned"]},{"key":"m06-integrity-governance-and-the-written-case","title":"Integrity, Governance and the Written Case","lesson_keys":["l01-conflicts-of-interest-and-gifts","l02-fraud-and-corruption-in-execution","l03-governance-and-assurance","l04-reading-the-sources-as-they-change","l05-the-written-case-brief"]}]}'::jsonb) then
    raise exception 'SC5 go-live refused: the advanced structure row is missing, inactive or not the manifest''s structure';
  end if;
  select string_agg(k, ', ' order by k) into v_bad from (
    select k from unnest(array['m01-contract-strategy', 'm02-claims', 'm03-disputes-and-their-resolution', 'm04-termination-step-in-and-exit', 'm05-close-out-and-lessons-learned', 'm06-integrity-governance-and-the-written-case']) k
     where (select count(*) from public.academy_quiz_questions q
             where q.app_slug = 'contracts' and q.tier = 'advanced' and q.scope = 'module'
               and q.module_key = k and q.active) <> 15) x;
  if v_bad is not null then
    raise exception 'SC5 go-live refused: advanced module bank(s) without exactly 15 active questions: %', v_bad;
  end if;
  select count(*) into v_n from public.academy_quiz_questions
   where app_slug = 'contracts' and tier = 'advanced' and scope = 'final' and active;
  if v_n <> 42 then
    raise exception 'SC5 go-live refused: the advanced final exam holds % active questions, not 42', v_n;
  end if;
  select count(*) into v_n from public.academy_quiz_questions where app_slug = 'contracts' and tier = 'advanced';
  if v_n <> 132 then
    raise exception 'SC5 go-live refused: the advanced tier holds % questions, not 132', v_n;
  end if;
  select md5(string_agg(tier || '|' || scope || '|' || coalesce(module_key, '') || '|' || ord || '|' || md5(prompt)
                        || '|' || md5(options->>0) || '|' || md5(options->>1) || '|' || md5(options->>2) || '|' || md5(options->>3)
                        || '|' || answer_index || '|' || md5(coalesce(explanation, '')), ','
                        order by case scope when 'module' then 0 else 1 end, left(coalesce(module_key, ''), 3), ord))
    into v_d
    from public.academy_quiz_questions where app_slug = 'contracts' and tier = 'advanced';
  if v_d is distinct from '4d6d6b60901b7e5d10d772d89ddb65e4' then
    raise exception 'SC5 go-live refused: the advanced questions are not the committed banks (content digest % where the banks give 4d6d6b60901b7e5d10d772d89ddb65e4)', v_d;
  end if;

  -- ------------------------------------------------- spread and copy, all tiers
  select string_agg(b, ', ' order by b) into v_bad from (
    select q.tier || '/' || coalesce(q.module_key, 'final') || ' index ' || i.i as b
      from (select distinct tier, scope, module_key from public.academy_quiz_questions where app_slug = 'contracts') q
      cross join generate_series(0, 3) i(i)
     where (select count(*) filter (where x.answer_index = i.i)::numeric / count(*)
              from public.academy_quiz_questions x
             where x.app_slug = 'contracts' and x.tier = q.tier and x.scope = q.scope
               and x.module_key is not distinct from q.module_key) not between 0.15 and 0.35) s;
  if v_bad is not null then
    raise exception 'SC5 go-live refused: answer indices outside the 15 to 35 per cent band: %', v_bad;
  end if;
  select string_agg(tier || '/' || coalesce(module_key, 'final') || '#' || ord, ', ') into v_bad
    from public.academy_quiz_questions
   where app_slug = 'contracts'
     and (jsonb_array_length(options) <> 4 or answer_index not between 0 and 3
          or coalesce(btrim(explanation), '') = '' or not active
          or (prompt || options::text || coalesce(explanation, '')) ~ '[\u2013\u2014]'
          or (prompt || options::text || coalesce(explanation, '')) ~ '\mP[0-9]{3}\M');
  if v_bad is not null then
    raise exception 'SC5 go-live refused: question(s) malformed, inactive, dashed or carrying a passage id: %', v_bad;
  end if;

  -- ------------------------------------------------------------- the flip
  update public.academy_apps set status = 'available'
   where slug = 'contracts' and status is distinct from 'available';
  if (select status from public.academy_apps where slug = 'contracts') <> 'available' then
    raise exception 'SC5 go-live refused: contracts did not read back available';
  end if;
  raise notice 'SC5 go-live: contracts available, a practice course: 3 tiers, 78 lessons, 396 questions, no capstone';
end $$;
